package users

import (
	"errors"
	"fmt"
)

// User is a directory entry.
type User struct {
	ID    string
	Email string
}

// Repository looks users up by ID. Lookups are slow.
type Repository interface {
	FindByID(id string) (User, error)
}

// ErrNotFound reports a missing user.
var ErrNotFound = errors.New("user not found")

// Directory answers questions about users through a Repository.
type Directory struct {
	repository Repository
}

// NewDirectory wires a Directory to its Repository.
func NewDirectory(repository Repository) Directory {
	return Directory{repository: repository}
}

// EmailOf returns the email address of the user with the given ID.
func (d Directory) EmailOf(id string) (string, error) {
	user, err := d.repository.FindByID(id)
	if err != nil {
		return "", fmt.Errorf("email of %q: %w", id, err)
	}
	return user.Email, nil
}
